NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'Micah'

CHAPTERS = {
    1: {
        1: 'Beseda Gospodova, ki je prišla Miheju Moréšečanu v dneh Jotáma, Aháza in Ezekíja, Judovih kraljev, ki jo je videl glede Samarije in Jeruzalema.',
        2: '»Poslušajte, vsa ve ljudstva, prisluhni, oh zemlja in vsi, ki so na njej, in naj bo Gospod Bog priča zoper vas, Gospod od svojega svetega templja.',
        3: 'Kajti glejte, Gospod prihaja iz svojega kraja in bo prišel dol in stopil na visoke kraje zemlje.',
        4: 'Gore bodo stopljene pod njim in doline bodo razklane kakor vosek pred ognjem in kakor vode, ki so izlite dol po strmini.',
        5: 'Zaradi Jakobovega prestopka je vse to in zaradi grehov Izraelove hiše. Kaj je Jakobov prestopek? Mar ni Samarija? In kaj so visoki Judovi kraji? Ali niso oni Jeruzalem?',
        6: 'Zato bom Samarijo naredil kakor kup polja in kakor zasajanje vinograda in njene kamne bom izlil dol v dolino in odkril bom njene temelje.',
        7: 'Vse njene rezane podobe bodo stolčene na koščke in vsa njena plačila bodo požgana z ognjem in vse njene malike bom pustil zapuščene, kajti to je zbirala od plačila pocestnice in vrnili se bodo k plačilu pocestnice.',
        8: 'Zato bom tarnal in tulil, šel bom slečen in nag. Naredil bom tarnanje kakor zmaji in žalovanje kakor sove.',
        9: 'Kajti njena rana je nezaceljiva, kajti ta je prišla v Juda; prišla je v velika vrata mojega ljudstva, celó do Jeruzalema.',
        10: 'Tega ne razglasite pri Gatu, sploh ne jokajte. V Bet Leáfri se valjajte v prahu.',
        11: 'Odidi proč, ti prebivalec Šafírja, ki imaš svojo sramoto golo. Prebivalec Caanána ne pridi naprej v žalovanju Bet Ecela; ta bo od vas prejel svojo postojanko.',
        12: 'Kajti prebivalec Maróta je skrbno čakal na dobro, toda zlo je prišlo dol od Gospoda k velikim vratom Jeruzalema.',
        13: 'Oh ti prebivalec Lahíša, naprezi bojni voz k hitri živali. Ta je začetek greha sionski hčeri, kajti prestopke Izraela je bilo najti v tebi.',
        14: 'Zato boš dal darila Moréšet Gatu. Ahzíbove hiše bodo laž Izraelovim kraljem.',
        15: 'Vendar bom k tebi privedel dediča, oh prebivalec Marešá. Prišel bo k Adulámu, Izraelovi slavi.',
        16: 'Naredi se plešast in ostriži se zaradi svojih prefinjenih otrok. Svojo plešavost povečaj kakor orel, kajti od tebe so odšli v ujetništvo.«',
    },
    2: {
        1: '»Gorje tistim, ki snujejo krivičnost in na svojih posteljah počnejo zlo! Ko je jutro svetlo, to izvajajo, ker je to v moči njihove roke.',
        2: 'Poželijo si polja in jih zavzamejo z nasiljem, hiše in si jih vzamejo. Tako zatirajo moža, njegovo hišo in njegovo dediščino, celo moža in njegovo dediščino.«',
        3: 'Zato tako govori Gospod: »Glej, zoper to družino snujem zlo, od katerega svojih vratov ne boste odstranili niti ne boste hodili ošabno, kajti ta čas je hud.',
        4: 'Na tisti dan bo nekdo vzel prispodobo zoper vas in žaloval z otožnim žalovanjem in rekel: ›Popolnoma bomo oplenjeni. Spremenil je delež mojega ljudstva. Kako je to odstranjeno od mene! Obračajoč se stran je razdelil naša polja.‹',
        5: 'Zato ne boš imel nobenega, ki bi z žrebom vrgel vrvico v Gospodovi skupnosti.',
        6: '»Ne prerokujte,« pravijo tistim, ki prerokujejo. Naj jim ne prerokujejo, da oni ne bi odvrnili sramote.',
        7: 'Oh ti, ki si poimenovan Jakobova hiša, mar je Gospodov duh omejen? Mar so to njegova dejanja? Ali moje besede ne delajo dobro tistemu, ki hodi pošteno?',
        8: 'Celo od davnine je moje ljudstvo vstalo kakor sovražnik. Ogrinjalo z oblačilom vlečete s tistih, ki varno hodijo mimo, kakor ljudje, ki so nasprotni vojni.',
        9: 'Ženske mojega ljudstva ste metali iz njihovih prijetnih hiš; njihovim otrokom ste mojo slavo vzeli na veke.',
        10: 'Vstanite in odidite, kajti to ni vaš počitek. Ker je ta [dežela] omadeževana, vas bo uničila, celo z bolečim uničenjem.',
        11: 'Če človek, ki hodi v duhu in neresnici, laže, rekoč: ›Prerokoval ti bom o vinu in o močni pijači,‹ bo ta torej prerok temu ljudstvu.',
        12: 'Zagotovo te bom vsega združil, oh Jakob, zagotovo bom zbral Izraelov preostanek. Skupaj jih bom postavil kakor ovce iz Bocre, kakor trop v sredi njihove staje. Naredili bodo velik hrup zaradi razloga množice ljudi.',
        13: 'Lomilec je prišel gor prednje. Vlomili so in prešli skozi velika vrata in pri njih odšli ven, in njihov kralj bo šel pred njimi in Gospod jim bo na čelu.«',
    },
    3: {
        1: 'Rekel sem: »Poslušajte, prosim vas, oh Jakobovi poglavarji in vi princi Izraelove hiše: › Mar ni to za vas, da poznate sodbo?‹',
        2: 'Ki sovražite dobro in ljubite zlo, ki njihovo kožo trgate iz njih in njihovo meso iz njihovih kosti,',
        3: 'ki tudi jeste meso mojega ljudstva in odirate njihovo kožo iz njih; in lomijo njihove kosti in jih sekajo na koščke, kakor za lonec in kakor meso znotraj kotla.',
        4: 'Potem bodo klicali h Gospodu, toda ne bo jih slišal. Ob tistem času bo celo svoj obraz skril pred njimi, kakor so se oni slabo obnašali v svojih ravnanjih.',
        5: 'Tako govori Gospod glede prerokov, ki mojemu ljudstvu povzročajo, da se moti, ki grizejo s svojimi zobmi in kličejo: ›Mir;‹ in kdor ne daje v njihova usta, pripravljajo celo vojno zoper njega.',
        6: 'Zato bo nad vami noč, da ne boste imeli videnja; in ta vam bo temna, da ne boste vedeževali; in sonce bo zašlo nad preroki in dan bo otemnel nad njimi.',
        7: 'Takrat bodo vidci osramočeni in vedeževalci zbegani. Da, vsi bodo pokrivali svoje ustnice, kajti tam ni odgovora od Boga.',
        8: 'Toda resnično, jaz sem po Gospodovem duhu poln oblasti, sodbe in moči, da Jakobu razglasim njegov prestopek in Izraelu njegov greh.',
        9: 'Poslušajte to, prosim vas, vi poglavarji Jakobove hiše in princi Izraelove hiše, ki se vam gnusi sodba in izkrivljate vso pravico.',
        10: 'Sion gradijo s krvjo in Jeruzalem s krivičnostjo.',
        11: 'Njihovi poglavarji sodijo zaradi nagrade in njihovi duhovniki učijo zaradi plačila in preroki vedežujejo zaradi denarja. Vendar ali se bodo naslonili na Gospoda in rekli: › Mar ni Gospod med nami? Nobeno zlo ne more priti nad nas.‹',
        12: 'Zato bo zaradi vas Sion preoran kakor polje in Jeruzalem bo spremenjen v razvaline in gore [te] hiše kakor visoki kraji gozda.«',
    },
    4: {
        1: 'Toda v poslednjih dneh se bo zgodilo, da bo gora hiše Gospodove utrjena na vrhu gora in ta bo povišana nad hribe, in ljudstvo se bo stekalo k njej.',
        2: 'In številni narodi bodo prišli ter rekli: »Pridite, pojdimo gor do Gospodove gore in do hiše Jakobovega Boga in učil nas bo svojih poti in hodili bomo po njegovih stezah, kajti postava bo izšla iz Siona in Gospodova beseda iz Jeruzalema.«',
        3: 'Sodil bo med mnogimi ljudstvi in oštel oddaljene močne narode in svoje meče bodo prekovali v lemeže in svoje sulice v obrezovalne kavlje. Narod ne bo vzdignil meča zoper narod niti se ne bodo več učili vojskovanja.',
        4: 'Temveč bodo sedeli, vsak pod svojo trto in pod svojim figovim drevesom in nihče jih ne bo strašil, kajti usta Gospoda nad bojevniki so to govorila.',
        5: 'Kajti vsa ljudstva bodo hodila, vsako v imenu svojega boga, mi pa bomo hodili v imenu Gospoda, svojega Boga, na veke vekov.',
        6: 'Na ta dan,« govori Gospod, »bom zbral tisto, kar šepa in zbral tisto, kar je izgnano in tisto, kar sem prizadel.',
        7: 'Tisto, kar šepa, bom naredil ostanek in tisto, ki je bilo vrženo daleč proč, močan narod, in Gospod bo kraljeval nad njimi na gori Sion od zdaj naprej, celo na veke.',
        8: 'Ti pa, oh stolp tropa, oporišče hčere sionske, k tebi bo prišlo, celo prvo gospostvo, kraljestvo bo prišlo k jeruzalemski hčeri.',
        9: 'Zakaj torej kričiš na glas? Mar ni kralja v tebi? Je tvoj svetovalec izginil? Kajti ostre bolečine so te zgrabile kakor žensko v porodnih mukah.',
        10: 'Bodi v bolečini in trudi se, da rodiš, oh hči sionska, kakor ženska v porodnih mukah, kajti sedaj boš šla naprej iz mesta in prebivala boš na polju in šla boš celo do Babilona. Tam boš osvobojena, tam te bo Gospod odkupil iz roke tvojih sovražnikov.',
        11: 'Sedaj je tudi mnogo narodov zbranih zoper tebe, ki pravijo: ›Naj bo omadeževana in naj naše oko gleda na Sion.',
        12: 'Toda oni ne poznajo Gospodovih misli niti ne razumejo njegovega nasveta, kajti zbral jih bo kakor snope na mlatišču.',
        13: 'Vzdigni se in mlati, oh hči sionska, kajti tvoj rog bom naredil železo in tvoja kopita bom naredil bron. Na koščke boš zdrobila številna ljudstva in njihov dobiček bom posvetil Gospodu in njihovo imetje Gospodu celotne zemlje.«',
    },
    5: {
        1: 'Sedaj se zberi v krdela, oh hči krdel. Zoper nas je položil obleganje. Izraelovega sodnika bodo s palico udarjali na lice.',
        2: '§ Toda ti, Betlehem Efráta, čeprav si majhen med Judovimi tisočimi, vendar bo iz tebe prišel k meni tisti, ki bo vladar v Izraelu, katerega izhodi so bili od davnine, od večnosti.',
        3: 'Zato jih bo predal do časa, ko tista, ki je imela porodne muke, rodi. Potem se bo preostanek njegovih bratov vrnil k Izraelovim otrokom.',
        4: 'In stal bo in pasel v Gospodovi moči, v veličastvu imena Gospoda, svojega Boga; in oni bodo prebivali, kajti sedaj bo velik do koncev zemlje.',
        5: 'In ta mož bo mir, ko bo Asirec prišel v našo deželo, in ko bo teptal v naših palačah, takrat bomo zoper njega vzdignili sedem pastirjev in osem glavnih mož.',
        6: 'In z mečem bodo opustošili deželo Asirije in Nimródovo deželo na njenih vhodih. Tako nas bo osvobodil pred Asirci, ko pride v našo deželo in ko mendra znotraj naših meja.',
        7: 'Jakobov preostanek bo v sredi številnih ljudstev, kakor rosa od Gospoda, kakor nalivi na travo, ki ne čakajo na človeka niti ne čakajo na človeške sinove.',
        8: 'Jakobov preostanek bo med pogani v sredi številnega ljudstva kakor lev med gozdnimi živalmi, kakor mlad lev med tropi ovc. Če gre ta skozi, tako pomendra kakor raztrga na koščke in nihče ne more osvoboditi.',
        9: 'Tvoja roka bo vzdignjena nad tvoje nasprotnike in vsi tvoji sovražniki bodo iztrebljeni.',
        10: 'In zgodilo se bo na tisti dan,« govori Gospod, »da bom iz tvoje srede iztrebil tvoje konje in uničil tvoje bojne vozove',
        11: 'in iztrebil bom mesta tvoje dežele in zrušil vsa tvoja oporišča',
        12: 'in iztrebil bom čaranja iz tvoje roke in ne boš več imel napovedovalcev usode.',
        13: 'Tudi tvoje rezane podobe bom iztrebil in tvoje stoječe podobe iz tvoje srede in ne boš več oboževal dela svojih rok.',
        14: 'Izruval bom tvoje ašere iz tvoje srede. Tako bom uničil tvoja mesta.',
        15: 'Nad pogani bom izvršil maščevanje v jezi in razjarjenosti, takšno, o kakršnem niso slišali.«',
    },
    6: {
        1: 'Poslušajte sedaj, kar govori Gospod: »Vstani, poteguj se pred gorami in naj hribi slišijo tvoj glas.',
        2: 'Prisluhnite, oh gore, Gospodovo polemiko in vi močni temelji zemlje, kajti Gospod ima polemiko s svojim ljudstvom in pravdal se bo z Izraelom.',
        3: 'Oh moje ljudstvo, kaj sem ti storil? In v čem sem te izmučil? Pričaj zoper mene.',
        4: 'Kajti privedel sem te gor iz egiptovske dežele in te odkupil iz hiše služabnikov in pred teboj sem poslal Mojzesa, Arona in Mirjam.',
        5: 'Oh moje ljudstvo, spomnite se sedaj kaj je svetoval moábski kralj Balák, in kaj mu je Beórjev sin Bileám odgovoril iz Šitíma do Gilgála, da boste lahko spoznali Gospodovo pravičnost.',
        6: 'S čim bom prišel pred Gospoda in se priklonil pred vzvišenim Bogom? Naj pridem predenj z žgalnimi daritvami, z enoletnimi teleti?',
        7: 'Mar bo Gospod zadovoljen s tisoči ovnov ali z deset tisočimi rekami olja? Naj dam svojega prvorojenca za svoj prestopek, sad mojega telesa za greh moje duše?',
        8: 'Pokazal ti je, oh človek, kaj je dobro. Kaj zahteva Gospod od tebe, razen da ravnaš pravično, da ljubiš usmiljenje in da ponižno hodiš s svojim Bogom?',
        9: '§ Gospodov glas kliče v mesto in človek modrosti bo videl tvoje ime. Poslušaj palico in tistega, ki jo je določil.',
        10: '§ Ali so še zakladi zlobnosti v hiši zlobnega in skopa mera, kar je gnusno?',
        11: 'Mar jih bom štel za čiste z zlobnimi tehtnicami in s torbo varljivih uteži?',
        12: 'Kajti njegovi bogataši so polni nasilja in njegovi prebivalci so govorili laži in njihov jezik je varljiv v njihovih ustih.',
        13: 'Zato te bom tudi jaz naredil bolnega, ko te bom udarjal, ko te bom pustošil zaradi tvojih grehov.',
        14: 'Jedel boš, toda ne boš nasičen in tvoja sestradanost bo v tvoji sredi in prijel boš, toda ne boš rešil in to, kar rešiš, bom izročil meču.',
        15: 'Sejal boš, toda ne boš žel; tlačil olive, toda z oljem se ne boš mazilil; in sladko vino, toda vina ne boš pil.',
        16: 'Kajti držijo se Omrijevih zakonov in vseh del Ahábove hiše in vi se ravnate po njihovih nasvetih, da bi te naredil za opustošenje in njegove prebivalce za posmeh. Zatorej boste nosili grajo mojega ljudstva.',
    },
    7: {
        1: 'Gorje meni! Kajti sem kakor, ko so zbrali poletne sadove, kakor paberkovanje grozdne trgatve. Tam ni nobenega grozda, da bi ga jedel; moja duša si je želela prvi sad.',
        2: 'Dober človek je izginil z zemlje in nobenega poštenega ni med ljudmi. Vsi v zasedi prežijo na kri, vsak svojega brata z mrežo lovi.',
        3: 'Da lahko počnejo zlo, iskreno, z obema rokama. Princ zahteva in sodnik povprašuje po nagradi. In velik človek, on izreka svojo pogubno željo. Tako to sprevračajo.',
        4: 'Najboljši izmed njih je kakor osat. Najpokončnejši je ostrejši, kakor trnova ograja. Dan tvojih stražarjev in tvojega obiskanja prihaja; sedaj bo [to] njihova zmedenost.',
        5: 'Ne zaupaj prijatelju, ne položi zaupanja v vodiča, varuj vrata svojih ust pred njo, ki leži v tvojem naročju.',
        6: 'Kajti sin ne spoštuje očeta, hči se vzdiguje zoper svojo mater, snaha zoper svojo taščo. Človeku so sovražniki ljudje iz njegove lastne hiše.',
        7: 'Zatorej bom gledal h Gospodu, čakal bom na Boga rešitve moje duše. Moj Bog me bo slišal.',
        8: 'Ne razveseljuj se zoper mene, oh moja sovražnica. Ko padem, bom vstal; ko sedim v temi, mi bo Gospod svetloba.',
        9: 'Prenašal bom Gospodovo ogorčenje, ker sem grešil zoper njega, dokler ne brani mojega primera in ne izvrši sodbe zame. Privedel me bo k svetlobi in gledal bom njegovo pravičnost.',
        10: 'Potem bo tista, ki je moja sovražnica, to videla in sramota bo pokrila tisto, ki mi je rekla; ›Kje je Gospod, tvoj Bog?‹ Moje oči jo bodo gledale. Sedaj bo pomendrana kakor ulično blato.',
        11: '§ Na dan, ko naj bi bili zgrajeni tvoji zidovi, na tisti dan bo odlok odstranjen daleč.',
        12: 'Na ta dan bo tudi on prišel k tebi, celo iz Asirije in od utrjenih mest in od trdnjave, celo do reke in od morja do morja in od gore do gore.',
        13: 'Vendar bo dežela zapuščena zaradi tistih, ki prebivajo v njej, zaradi sadov njihovih početij.',
        14: 'Pasi svoje ljudstvo s svojo palico, trop svoje dediščine, ki prebiva osamljeno v goščavi, v sredi Karmela. Naj se pasejo v Bašánu in Gileádu, kakor v dneh davnine.',
        15: 'Kakor v dneh tvojega prihoda iz egiptovske dežele mu bom pokazal čudovite stvari.',
        16: 'Narodi bodo videli in bodo zbegani ob vsej njihovi moči. Svojo roko bodo položili na svoja usta, njihova ušesa bodo gluha.',
        17: 'Prah bodo lizali kakor kača, iz svojih lukenj bodo prilezli kakor črvi zemlje. Bali se bodo Gospoda, našega Boga in bali se bodo zaradi tebe.',
        18: 'Kdo je Bog, podoben tebi, ki oprošča krivičnost in gre mimo prestopka, preostanka svoje dediščine? Svoje jeze ne ohranja na veke, ker se razveseljuje v usmiljenju.',
        19: 'Ponovno se bo obrnil, nad nami bo imel sočutje, podjarmil bo naše krivičnosti in vse njihove grehe boš vrgel v globine morja.',
        20: 'Jakobu boš izvršil resnico in Abrahamu usmiljenje, ki si ga od dni davnine prisegel našim očetom.',
    },
}
